        "content": "import { describe, expect, test, beforeAll, afterAll } from \"bun:test\";\nimport { mkdtemp, rm } from \"node:fs/promises\";\nimport { tmpdir } from \"node:os\";\nimport { join } from \"node:path\";\n\nconst CLI_PATH = join(import.meta.dir, \"validate-yaml.ts\");\n\nasync function runCli(\n  args: string[]\n): Promise<{ stdout: string; stderr: string; exitCode: number }> {\n  const proc = Bun.spawn([\"bun\", \"run\", CLI_PATH, ...args], {\n    stdout: \"pipe\",\n    stderr: \"pipe\",\n  });\n\n  const [stdout, stderr] = await Promise.all([\n    new Response(proc.stdout).text(),\n    new Response(proc.stderr).text(),\n  ]);\n\n  const exitCode = await proc.exited;\n\n  return { stdout, stderr, exitCode };\n}\n\ndescribe(\"validate-yaml CLI integration tests\", () => {\n  let tempDir: string;\n\n  beforeAll(async () => {\n    tempDir = await mkdtemp(join(tmpdir(), \"yaml-validator-test-\"));\n  });\n\n  afterAll(async () => {\n    await rm(tempDir, { recursive: true, force: true });\n  });\n\n  test(\"valid YAML file outputs success message to stdout and exits with code 0\", async () => {\n    const filePath = join(tempDir, \"valid.yaml\");\n    await Bun.write(filePath, \"key: value\\nlist:\\n  - item1\\n  - item2\\n\");\n\n    const { stdout, stderr, exitCode } = await runCli([filePath]);\n\n    expect(stdout.trim()).toBe(`Valid YAML: ${filePath}`);\n    expect(stderr).toBe(\"\");\n    expect(exitCode).toBe(0);\n  });\n\n  test(\"invalid YAML file outputs error message to stderr and exits with code 1\", async () => {\n    const filePath = join(tempDir, \"invalid.yaml\");\n    await Bun.write(filePath, 'key: \"unclosed string');\n\n    const { stdout, stderr, exitCode } = await runCli([filePath]);\n\n    expect(stdout).toBe(\"\");\n    expect(stderr).toContain(filePath);\n    expect(stderr).toContain(\":\");\n    expect(exitCode).toBe(1);\n  });\n\n  test(\"missing file outputs 'File not found' to stderr and exits with code 1\", async () => {\n    const filePath = join(tempDir, \"nonexistent.yaml\");\n\n    const { stdout, stderr, exitCode } = await runCli([filePath]);\n\n    expect(stdout).toBe(\"\");\n    expect(stderr).toContain(\"File not found\");\n    expect(stderr).toContain(filePath);\n    expect(exitCode).toBe(1);\n  });\n\n  test(\"no argument outputs usage message to stderr and exits with code 1\", async () => {\n    const { stdout, stderr, exitCode } = await runCli([]);\n\n    expect(stdout).toBe(\"\");\n    expect(stderr).toContain(\"Usage:\");\n    expect(exitCode).toBe(1);\n  });\n\n  test(\"empty file outputs success message and exits with code 0\", async () => {\n    const filePath = join(tempDir, \"empty.yaml\");\n    await Bun.write(filePath, \"\");\n\n    const { stdout, stderr, exitCode } = await runCli([filePath]);\n\n    expect(stdout.trim()).toBe(`Valid YAML: ${filePath}`);\n    expect(stderr).toBe(\"\");\n    expect(exitCode).toBe(0);\n  });\n});\n"
