        "content": "/**\n * CLI entry point for YAML validator\n * Validates YAML files for syntax correctness\n */\n\nimport { tokenize, LexerError } from \"../yaml/lexer\";\nimport { validate } from \"../yaml/parser\";\n\nasync function main(): Promise<void> {\n  const filePath = process.argv[2];\n\n  if (!filePath) {\n    console.error(\"Usage: bun run src/cli/validate-yaml.ts <file>\");\n    process.exit(1);\n  }\n\n  const file = Bun.file(filePath);\n\n  if (!(await file.exists())) {\n    console.error(`Error: File not found: ${filePath}`);\n    process.exit(1);\n  }\n\n  const content = await file.text();\n\n  try {\n    const tokens = tokenize(content);\n    const result = validate(tokens);\n\n    if (result.valid) {\n      console.log(`Valid YAML: ${filePath}`);\n      process.exit(0);\n    } else {\n      const { error } = result;\n      console.error(\n        `${filePath}:${error.position.line}:${error.position.column}: ${error.message}`\n      );\n      process.exit(1);\n    }\n  } catch (err) {\n    if (err instanceof LexerError) {\n      console.error(\n        `${filePath}:${err.position.line}:${err.position.column}: ${err.message}`\n      );\n      process.exit(1);\n    }\n    throw err;\n  }\n}\n\nmain();\n"
