        "content": "import { describe, expect, test } from \"bun:test\";\nimport { tokenize } from \"./lexer\";\nimport { validate } from \"./parser\";\n\nfunction validateYaml(input: string) {\n  const tokens = tokenize(input);\n  return validate(tokens);\n}\n\ndescribe(\"parser\", () => {\n  test(\"empty document returns valid: true\", () => {\n    const result = validateYaml(\"\");\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"comment-only document returns valid: true\", () => {\n    const result = validateYaml(\"# this is a comment\");\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"simple mapping returns valid: true\", () => {\n    const result = validateYaml(\"key: value\");\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"nested mapping returns valid: true\", () => {\n    const result = validateYaml(\"a:\\n  b: c\");\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"sequence returns valid: true\", () => {\n    const result = validateYaml(\"- a\\n- b\");\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"mixed structure (mapping with sequence values) returns valid: true\", () => {\n    const result = validateYaml(\"list:\\n  - item1\\n  - item2\");\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"invalid indentation returns valid: false with error position\", () => {\n    const result = validateYaml(\"a:\\n  b: c\\n d: e\");\n    expect(result.valid).toBe(false);\n\n    if (!result.valid) {\n      expect(result.error.position.line).toBeGreaterThan(0);\n      expect(result.error.position.column).toBeGreaterThan(0);\n      expect(result.error.message).toContain(\"indentation\");\n    }\n  });\n\n  test(\"tab character returns valid: false (tabs not allowed)\", () => {\n    const result = validateYaml(\"\\tkey: value\");\n    expect(result.valid).toBe(false);\n\n    if (!result.valid) {\n      expect(result.error.message.toLowerCase()).toContain(\"tab\");\n    }\n  });\n});\n"
