input.content:
/**
 * YAML Parser/Validator - Validates token stream against YAML syntax rules
 * Stream-based validation with fail-fast error reporting
 */

import type { Token, TokenType, Position, YamlError, ValidationResult } from "./types";

/**
 * Internal parser state
 */
interface ParserState {
  tokens: Token[];
  current: number;
  indentStack: number[];
  inDocument: boolean;
  afterDocumentEnd: boolean;
}

/**
 * Create initial parser state
 */
function createState(tokens: Token[]): ParserState {
  return {
    tokens,
    current: 0,
    indentStack: [0],
    inDocument: false,
    afterDocumentEnd: false,
  };
}

/**
 * Check if we've reached the end of tokens
 */
function isAtEnd(state: ParserState): boolean {
  return state.current >= state.tokens.length;
}

/**
 * Get current token
 */
function currentToken(state: ParserState): Token | undefined {
  return state.tokens[state.current];
}

/**
 * Peek at token at offset from current position
 */
function peekToken(state: ParserState, offset: number = 1): Token | undefined {
  return state.tokens[state.current + offset];
}

/**
 * Advance to next token and return the previous one
 */
function advance(state: ParserState): Token | undefined {
  if (!isAtEnd(state)) {
    return state.tokens[state.current++];
  }
  return undefined;
}

/**
 * Get the top of the indent stack
 */
function currentIndentLevel(state: ParserState): number {
  return state.indentStack[state.indentStack.length - 1] ?? 0;
}

/**
 * Create a validation error result
 */
function error(message: string, position: Position, context?: string): ValidationResult {
  return {
    valid: false,
    error: {
      message,
      position,
      context,
    },
  };
}

/**
 * Check if a token is a value token (can follow mapping key or sequence entry)
 */
function isValueToken(token: Token | undefined): boolean {
  if (!token) return false;
  const valueTypes: TokenType[] = [
    "SCALAR",
    "QUOTED_SCALAR",
    "LITERAL_BLOCK",
    "FOLDED_BLOCK",
    "ANCHOR",
    "ALIAS",
    "TAG",
    "SEQUENCE_ENTRY",
    "MAPPING_KEY",
  ];
  return valueTypes.includes(token.type);
}

/**
 * Check if token is whitespace-like (newline, comment, indent)
 */
function isWhitespaceToken(token: Token | undefined): boolean {
  if (!token) return false;
  return token.type === "NEWLINE" || token.type === "COMMENT" || token.type === "INDENT";
}

/**
 * Check if a token indicates document content
 */
function isContentToken(token: Token | undefined): boolean {
  if (!token) return false;
  const contentTypes: TokenType[] = [
    "SCALAR",
    "QUOTED_SCALAR",
    "MAPPING_KEY",
    "SEQUENCE_ENTRY",
    "LITERAL_BLOCK",
    "FOLDED_BLOCK",
    "ANCHOR",
    "ALIAS",
    "TAG",
  ];
  return contentTypes.includes(token.type);
}

/**
 * Skip whitespace tokens (newlines, comments, indents)
 * Returns the last indent token seen (for tracking indentation)
 */
function skipWhitespace(state: ParserState): Token | undefined {
  let lastIndent: Token | undefined;

  while (!isAtEnd(state)) {
    const token = currentToken(state);
    if (!token) break;

    if (token.type === "NEWLINE" || token.type === "COMMENT") {
      advance(state);
    } else if (token.type === "INDENT") {
      lastIndent = advance(state);
    } else {
      break;
    }
  }

  return lastIndent;
}

/**
 * Validate indentation using stack algorithm
 * Returns error if indentation is invalid, undefined otherwise
 */
function validateIndentation(state: ParserState, indent: number, position: Position): ValidationResult | undefined {
  const currentLevel = currentIndentLevel(state);

  if (indent > currentLevel) {
    state.indentStack.push(indent);
  } else if (indent < currentLevel) {
    while (state.indentStack.length > 1 && currentIndentLevel(state) > indent) {
      state.indentStack.pop();
    }

    if (currentIndentLevel(state) !== indent) {
      return error(
        `Invalid indentation: expected ${currentIndentLevel(state)} spaces, got ${indent}`,
        position
      );
    }
  }

  return undefined;
}

/**
 * Validate a block scalar (literal | or folded >)
 */
function validateBlockScalar(state: ParserState, blockToken: Token): ValidationResult | undefined {
  const blockIndent = blockToken.indent;

  while (!isAtEnd(state)) {
    const token = currentToken(state);
    if (!token || token.type === "EOF") break;

    if (token.type === "NEWLINE") {
      advance(state);
      continue;
    }

    if (token.type === "INDENT") {
      const indentToken = advance(state);
      if (!indentToken) break;

      const nextToken = currentToken(state);
      if (!nextToken || nextToken.type === "EOF" || nextToken.type === "NEWLINE") {
        continue;
      }

      if (indentToken.indent <= blockIndent) {
        state.current--;
        return undefined;
      }

      if (nextToken.type === "SCALAR" || nextToken.type === "QUOTED_SCALAR") {
        advance(state);
      } else if (nextToken.type === "MAPPING_KEY" || nextToken.type === "SEQUENCE_ENTRY") {
        state.current--;
        return undefined;
      }
      continue;
    }

    if (token.type === "COMMENT") {
      advance(state);
      continue;
    }

    if (token.type === "SCALAR" || token.type === "QUOTED_SCALAR") {
      if (token.indent <= blockIndent) {
        return undefined;
      }
      advance(state);
      continue;
    }

    return undefined;
  }

  return undefined;
}

/**
 * Validate a mapping key and its value
 */
function validateMapping(state: ParserState, keyToken: Token): ValidationResult | undefined {
  const nextToken = currentToken(state);

  if (!nextToken || nextToken.type === "EOF") {
    return undefined;
  }

  if (nextToken.type === "NEWLINE" || nextToken.type === "COMMENT") {
    return undefined;
  }

  if (isValueToken(nextToken)) {
    if (nextToken.type === "LITERAL_BLOCK" || nextToken.type === "FOLDED_BLOCK") {
      const blockToken = advance(state);
      if (blockToken) {
        return validateBlockScalar(state, blockToken);
      }
    }
    return undefined;
  }

  return error(
    "Expected value after mapping key",
    nextToken.position,
    keyToken.value
  );
}

/**
 * Validate a sequence entry
 */
function validateSequence(state: ParserState, entryToken: Token): ValidationResult | undefined {
  const nextToken = currentToken(state);

  if (!nextToken || nextToken.type === "EOF") {
    return undefined;
  }

  if (nextToken.type === "NEWLINE" || nextToken.type === "COMMENT") {
    return undefined;
  }

  if (nextToken.type === "INDENT") {
    return undefined;
  }

  if (isValueToken(nextToken)) {
    if (nextToken.type === "LITERAL_BLOCK" || nextToken.type === "FOLDED_BLOCK") {
      const blockToken = advance(state);
      if (blockToken) {
        return validateBlockScalar(state, blockToken);
      }
    }
    return undefined;
  }

  return error(
    "Expected value after sequence indicator",
    nextToken.position
  );
}

/**
 * Validate document markers appear only at document boundaries
 */
function validateDocumentMarker(state: ParserState, token: Token): ValidationResult | undefined {
  if (token.type === "DOCUMENT_START") {
    if (state.inDocument && !state.afterDocumentEnd) {
      const prevTokenIdx = state.current - 2;
      if (prevTokenIdx >= 0) {
        const prevToken = state.tokens[prevTokenIdx];
        if (prevToken && isContentToken(prevToken)) {
          return error(
            "Unexpected document marker",
            token.position
          );
        }
      }
    }
    state.inDocument = true;
    state.afterDocumentEnd = false;
    return undefined;
  }

  if (token.type === "DOCUMENT_END") {
    state.afterDocumentEnd = true;
    return undefined;
  }

  return undefined;
}

/**
 * Check for tab characters in token values or positions
 */
function checkForTabs(tokens: Token[]): ValidationResult | undefined {
  for (const token of tokens) {
    if (token.type === "INDENT" && token.value.includes("\t")) {
      return error(
        "Tabs are not allowed for indentation, use spaces only",
        token.position
      );
    }

    if (token.value.includes("\t") && token.type !== "QUOTED_SCALAR" && token.type !== "SCALAR") {
      return error(
        "Tabs are not allowed for indentation, use spaces only",
        token.position
      );
    }
  }

  return undefined;
}

/**
 * Main validate function
 * Accepts Token[] and returns ValidationResult
 */
export function validate(tokens: Token[]): ValidationResult {
  if (tokens.length === 0) {
    return { valid: true };
  }

  if (tokens.length === 1 && tokens[0].type === "EOF") {
    return { valid: true };
  }

  const tabError = checkForTabs(tokens);
  if (tabError) {
    return tabError;
  }

  const state = createState(tokens);

  while (!isAtEnd(state)) {
    const token = currentToken(state);
    if (!token) break;

    if (token.type === "EOF") {
      break;
    }

    if (token.type === "DOCUMENT_START" || token.type === "DOCUMENT_END") {
      advance(state);
      const markerError = validateDocumentMarker(state, token);
      if (markerError) {
        return markerError;
      }
      continue;
    }

    if (token.type === "NEWLINE" || token.type === "COMMENT") {
      advance(state);
      continue;
    }

    if (token.type === "INDENT") {
      const indentToken = advance(state);
      if (indentToken) {
        const indentError = validateIndentation(state, indentToken.indent, indentToken.position);
        if (indentError) {
          return indentError;
        }
      }
      continue;
    }

    if (token.type === "MAPPING_KEY") {
      advance(state);
      const mappingError = validateMapping(state, token);
      if (mappingError) {
        return mappingError;
      }
      continue;
    }

    if (token.type === "SEQUENCE_ENTRY") {
      advance(state);
      const sequenceError = validateSequence(state, token);
      if (sequenceError) {
        return sequenceError;
      }
      continue;
    }

    if (token.type === "LITERAL_BLOCK" || token.type === "FOLDED_BLOCK") {
      const blockToken = advance(state);
      if (blockToken) {
        const blockError = validateBlockScalar(state, blockToken);
        if (blockError) {
          return blockError;
        }
      }
      continue;
    }

    if (token.type === "SCALAR" || token.type === "QUOTED_SCALAR") {
      advance(state);
      continue;
    }

    if (token.type === "ANCHOR" || token.type === "ALIAS" || token.type === "TAG") {
      advance(state);
      continue;
    }

    advance(state);
  }

  return { valid: true };
}

