/**
 * Type definitions for YAML validator
 * Used by lexer and parser modules
 */

/**
 * Position tracking for error reporting
 */
export interface Position {
  line: number; // 1-indexed
  column: number; // 1-indexed
  offset: number; // 0-indexed byte offset
}

/**
 * Token types produced by lexer
 */
export type TokenType =
  | "DOCUMENT_START" // ---
  | "DOCUMENT_END" // ...
  | "MAPPING_KEY" // key:
  | "MAPPING_VALUE" // : (after key)
  | "SEQUENCE_ENTRY" // - (list item)
  | "SCALAR" // string, number, boolean, null
  | "QUOTED_SCALAR" // "string" or 'string'
  | "LITERAL_BLOCK" // |
  | "FOLDED_BLOCK" // >
  | "ANCHOR" // &name
  | "ALIAS" // *name
  | "TAG" // !tag
  | "INDENT" // indentation change
  | "NEWLINE" // line break
  | "COMMENT" // # comment
  | "EOF"; // end of file

/**
 * Token produced by the lexer
 */
export interface Token {
  type: TokenType;
  value: string;
  position: Position;
  indent: number; // indentation level (spaces)
}

/**
 * Validation errors with location
 */
export interface YamlError {
  message: string;
  position: Position;
  context?: string; // surrounding text for context
}

/**
 * Result of validation
 */
export type ValidationResult =
  | { valid: true }
  | { valid: false; error: YamlError };

/**
 * YAML Lexer - Tokenizes YAML input for validation
 * Performs single-pass tokenization with position tracking
 */

import type { Token, TokenType, Position, YamlError } from "./types";

/**
 * Lexer error thrown when tokenization fails
 */
export class LexerError extends Error {
  constructor(
    message: string,
    public position: Position,
    public context?: string
  ) {
    super(message);
    this.name = "LexerError";
  }

  toYamlError(): YamlError {
    return {
      message: this.message,
      position: this.position,
      context: this.context,
    };
  }
}

/**
 * Internal lexer state
 */
interface LexerState {
  input: string;
  position: Position;
  tokens: Token[];
  index: number;
}

/**
 * Create initial lexer state
 */
function createState(input: string): LexerState {
  return {
    input,
    position: { line: 1, column: 1, offset: 0 },
    tokens: [],
    index: 0,
  };
}

/**
 * Check if we've reached the end of input
 */
function isAtEnd(state: LexerState): boolean {
  return state.index >= state.input.length;
}

/**
 * Get current character
 */
function current(state: LexerState): string {
  return state.input[state.index] ?? "";
}

/**
 * Peek at character at offset from current position
 */
function peek(state: LexerState, offset: number = 1): string {
  return state.input[state.index + offset] ?? "";
}

/**
 * Advance position by one character
 */
function advance(state: LexerState): string {
  const char = current(state);
  state.index++;
  state.position.offset++;

  if (char === "\n") {
    state.position.line++;
    state.position.column = 1;
  } else {
    state.position.column++;
  }

  return char;
}

/**
 * Check if at start of line (column 1)
 */
function isAtLineStart(state: LexerState): boolean {
  return state.position.column === 1;
}

/**
 * Create a token and add to tokens list
 */
function addToken(
  state: LexerState,
  type: TokenType,
  value: string,
  startPosition: Position,
  indent: number
): void {
  state.tokens.push({
    type,
    value,
    position: { ...startPosition },
    indent,
  });
}

/**
 * Calculate current indentation level (spaces at start of line)
 */
function getCurrentIndent(state: LexerState): number {
  if (state.position.column === 1) {
    return 0;
  }

  let lineStart = state.index - (state.position.column - 1);
  let indent = 0;

  while (lineStart + indent < state.index && state.input[lineStart + indent] === " ") {
    indent++;
  }

  return indent;
}

/**
 * Skip whitespace (spaces only, not newlines)
 */
function skipSpaces(state: LexerState): void {
  while (!isAtEnd(state) && current(state) === " ") {
    advance(state);
  }
}

/**
 * Match a string at current position
 */
function match(state: LexerState, str: string): boolean {
  for (let i = 0; i < str.length; i++) {
    if (state.input[state.index + i] !== str[i]) {
      return false;
    }
  }
  return true;
}

/**
 * Check if character is a word character (for anchors, aliases)
 */
function isWordChar(char: string): boolean {
  return /[\w-]/.test(char);
}

/**
 * Check if character is non-whitespace (for tags)
 */
function isNonWhitespace(char: string): boolean {
  return char !== "" && !/\s/.test(char);
}

/**
 * Scan indentation at start of line
 */
function scanIndent(state: LexerState): number {
  const startPos = { ...state.position };
  let indent = 0;

  while (!isAtEnd(state) && current(state) === " ") {
    indent++;
    advance(state);
  }

  if (indent > 0) {
    addToken(state, "INDENT", " ".repeat(indent), startPos, indent);
  }

  return indent;
}

/**
 * Scan document start marker (---)
 */
function scanDocumentStart(state: LexerState, indent: number): boolean {
  if (!match(state, "---")) {
    return false;
  }

  const nextChar = state.input[state.index + 3];
  if (nextChar !== undefined && nextChar !== "\n" && nextChar !== " " && nextChar !== "\r") {
    return false;
  }

  const startPos = { ...state.position };
  advance(state);
  advance(state);
  advance(state);
  addToken(state, "DOCUMENT_START", "---", startPos, indent);
  return true;
}

/**
 * Scan document end marker (...)
 */
function scanDocumentEnd(state: LexerState, indent: number): boolean {
  if (!match(state, "...")) {
    return false;
  }

  const nextChar = state.input[state.index + 3];
  if (nextChar !== undefined && nextChar !== "\n" && nextChar !== " " && nextChar !== "\r") {
    return false;
  }

  const startPos = { ...state.position };
  advance(state);
  advance(state);
  advance(state);
  addToken(state, "DOCUMENT_END", "...", startPos, indent);
  return true;
}

/**
 * Scan comment (# to end of line)
 */
function scanComment(state: LexerState, indent: number): boolean {
  if (current(state) !== "#") {
    return false;
  }

  const startPos = { ...state.position };
  let value = "";

  while (!isAtEnd(state) && current(state) !== "\n") {
    value += advance(state);
  }

  addToken(state, "COMMENT", value, startPos, indent);
  return true;
}

/**
 * Scan newline
 */
function scanNewline(state: LexerState, indent: number): boolean {
  if (current(state) !== "\n") {
    return false;
  }

  const startPos = { ...state.position };
  advance(state);
  addToken(state, "NEWLINE", "\n", startPos, indent);
  return true;
}

/**
 * Scan sequence entry (- followed by space or newline)
 */
function scanSequenceEntry(state: LexerState, indent: number): boolean {
  if (current(state) !== "-") {
    return false;
  }

  const nextChar = peek(state);
  if (nextChar !== " " && nextChar !== "\n" && nextChar !== "") {
    return false;
  }

  const startPos = { ...state.position };
  advance(state);
  addToken(state, "SEQUENCE_ENTRY", "-", startPos, indent);
  return true;
}

/**
 * Scan quoted string (single or double quotes)
 */
function scanQuotedString(state: LexerState, indent: number): boolean {
  const quoteChar = current(state);
  if (quoteChar !== '"' && quoteChar !== "'") {
    return false;
  }

  const startPos = { ...state.position };
  let value = "";
  value += advance(state);

  while (!isAtEnd(state)) {
    const char = current(state);

    if (char === quoteChar) {
      value += advance(state);
      addToken(state, "QUOTED_SCALAR", value, startPos, indent);
      return true;
    }

    if (char === "\\" && quoteChar === '"') {
      value += advance(state);
      if (!isAtEnd(state)) {
        value += advance(state);
      }
    } else if (char === "\n") {
      throw new LexerError(
        `Unclosed quoted string starting with ${quoteChar}`,
        startPos,
        value
      );
    } else {
      value += advance(state);
    }
  }

  throw new LexerError(
    `Unclosed quoted string starting with ${quoteChar}`,
    startPos,
    value
  );
}

/**
 * Scan literal block indicator (|)
 */
function scanLiteralBlock(state: LexerState, indent: number): boolean {
  if (current(state) !== "|") {
    return false;
  }

  const startPos = { ...state.position };
  let value = advance(state);

  while (!isAtEnd(state) && (current(state) === "+" || current(state) === "-" || /\d/.test(current(state)))) {
    value += advance(state);
  }

  addToken(state, "LITERAL_BLOCK", value, startPos, indent);
  return true;
}

/**
 * Scan folded block indicator (>)
 */
function scanFoldedBlock(state: LexerState, indent: number): boolean {
  if (current(state) !== ">") {
    return false;
  }

  const startPos = { ...state.position };
  let value = advance(state);

  while (!isAtEnd(state) && (current(state) === "+" || current(state) === "-" || /\d/.test(current(state)))) {
    value += advance(state);
  }

  addToken(state, "FOLDED_BLOCK", value, startPos, indent);
  return true;
}

/**
 * Scan anchor (&name)
 */
function scanAnchor(state: LexerState, indent: number): boolean {
  if (current(state) !== "&") {
    return false;
  }

  const startPos = { ...state.position };
  let value = advance(state);

  while (!isAtEnd(state) && isWordChar(current(state))) {
    value += advance(state);
  }

  if (value.length > 1) {
    addToken(state, "ANCHOR", value, startPos, indent);
    return true;
  }

  return false;
}

/**
 * Scan alias (*name)
 */
function scanAlias(state: LexerState, indent: number): boolean {
  if (current(state) !== "*") {
    return false;
  }

  const startPos = { ...state.position };
  let value = advance(state);

  while (!isAtEnd(state) && isWordChar(current(state))) {
    value += advance(state);
  }

  if (value.length > 1) {
    addToken(state, "ALIAS", value, startPos, indent);
    return true;
  }

  return false;
}

/**
 * Scan tag (!tag)
 */
function scanTag(state: LexerState, indent: number): boolean {
  if (current(state) !== "!") {
    return false;
  }

  const startPos = { ...state.position };
  let value = advance(state);

  while (!isAtEnd(state) && isNonWhitespace(current(state))) {
    value += advance(state);
  }

  if (value.length > 1) {
    addToken(state, "TAG", value, startPos, indent);
    return true;
  }

  addToken(state, "TAG", value, startPos, indent);
  return true;
}

/**
 * Scan mapping key or scalar value
 * Returns true if a token was added
 */
function scanKeyOrScalar(state: LexerState, indent: number): boolean {
  if (isAtEnd(state)) {
    return false;
  }

  const startPos = { ...state.position };
  let value = "";

  while (!isAtEnd(state)) {
    const char = current(state);

    if (char === "\n" || char === "#") {
      break;
    }

    if (char === ":") {
      const nextChar = peek(state);
      if (nextChar === " " || nextChar === "\n" || nextChar === "" || nextChar === "\r") {
        value += advance(state);
        const trimmedKey = value.trimEnd();
        addToken(state, "MAPPING_KEY", trimmedKey, startPos, indent);
        return true;
      }
    }

    value += advance(state);
  }

  const trimmedValue = value.trim();
  if (trimmedValue.length > 0) {
    addToken(state, "SCALAR", trimmedValue, startPos, indent);
    return true;
  }

  return false;
}

/**
 * Tokenize a single line or content chunk
 */
function scanToken(state: LexerState, indent: number): boolean {
  if (isAtEnd(state)) {
    return false;
  }

  skipSpaces(state);

  if (isAtEnd(state)) {
    return false;
  }

  if (scanNewline(state, indent)) return true;
  if (scanComment(state, indent)) return true;
  if (scanSequenceEntry(state, indent)) return true;
  if (scanQuotedString(state, indent)) return true;
  if (scanLiteralBlock(state, indent)) return true;
  if (scanFoldedBlock(state, indent)) return true;
  if (scanAnchor(state, indent)) return true;
  if (scanAlias(state, indent)) return true;
  if (scanTag(state, indent)) return true;
  if (scanKeyOrScalar(state, indent)) return true;

  return false;
}

/**
 * Main tokenize function
 * Accepts string input and returns Token[]
 * Throws LexerError for lexical errors
 */
export function tokenize(input: string): Token[] {
  const state = createState(input);

  while (!isAtEnd(state)) {
    const atLineStart = isAtLineStart(state);

    if (atLineStart) {
      if (scanDocumentStart(state, 0)) continue;
      if (scanDocumentEnd(state, 0)) continue;

      const indent = scanIndent(state);

      if (!isAtEnd(state)) {
        scanToken(state, indent);
      }
    } else {
      const indent = getCurrentIndent(state);
      scanToken(state, indent);
    }
  }

  addToken(
    state,
    "EOF",
    "",
    { ...state.position },
    0
  );

  return state.tokens;
}

