/**
 * CLI entry point for YAML validator
 * Validates YAML files for syntax correctness
 */

import { tokenize, LexerError } from "../yaml/lexer";
import { validate } from "../yaml/parser";

async function main(): Promise<void> {
  const filePath = process.argv[2];

  if (!filePath) {
    console.error("Usage: bun run src/cli/validate-yaml.ts <file>");
    process.exit(1);
  }

  const file = Bun.file(filePath);

  if (!(await file.exists())) {
    console.error(`Error: File not found: ${filePath}`);
    process.exit(1);
  }

  const content = await file.text();

  try {
    const tokens = tokenize(content);
    const result = validate(tokens);

    if (result.valid) {
      console.log(`Valid YAML: ${filePath}`);
      process.exit(0);
    } else {
      const { error } = result;
      console.error(
        `${filePath}:${error.position.line}:${error.position.column}: ${error.message}`
      );
      process.exit(1);
    }
  } catch (err) {
    if (err instanceof LexerError) {
      console.error(
        `${filePath}:${err.position.line}:${err.position.column}: ${err.message}`
      );
      process.exit(1);
    }
    throw err;
  }
}

main();

import { describe, expect, test } from "bun:test";
import { tokenize, LexerError } from "./lexer";
import type { TokenType } from "./types";

function getTokenTypes(input: string): TokenType[] {
  const tokens = tokenize(input);
  return tokens.map((t) => t.type);
}

describe("lexer", () => {
  test("empty input returns [EOF]", () => {
    const types = getTokenTypes("");
    expect(types).toEqual(["EOF"]);
  });

  test("comment only input returns [COMMENT, EOF]", () => {
    const types = getTokenTypes("# this is a comment");
    expect(types).toEqual(["COMMENT", "EOF"]);
  });

  test("simple scalar returns [SCALAR, EOF]", () => {
    const types = getTokenTypes("hello");
    expect(types).toEqual(["SCALAR", "EOF"]);
  });

  test("mapping (key: value) returns correct token sequence", () => {
    const types = getTokenTypes("key: value");
    expect(types).toEqual(["MAPPING_KEY", "SCALAR", "EOF"]);
  });

  test("sequence (- item) returns correct token sequence", () => {
    const types = getTokenTypes("- item");
    expect(types).toEqual(["SEQUENCE_ENTRY", "SCALAR", "EOF"]);
  });

  test("nested mapping with indentation returns correct tokens including INDENT", () => {
    const types = getTokenTypes("a:\n  b: c");
    expect(types).toEqual([
      "MAPPING_KEY",
      "NEWLINE",
      "INDENT",
      "MAPPING_KEY",
      "SCALAR",
      "EOF",
    ]);
  });

  test("double quoted string returns QUOTED_SCALAR", () => {
    const types = getTokenTypes('"hello world"');
    expect(types).toEqual(["QUOTED_SCALAR", "EOF"]);

    const tokens = tokenize('"hello world"');
    expect(tokens[0].value).toBe('"hello world"');
  });

  test("single quoted string returns QUOTED_SCALAR", () => {
    const types = getTokenTypes("'hello world'");
    expect(types).toEqual(["QUOTED_SCALAR", "EOF"]);

    const tokens = tokenize("'hello world'");
    expect(tokens[0].value).toBe("'hello world'");
  });

  test("unclosed double quote returns LexerError with position", () => {
    expect(() => tokenize('"hello')).toThrow(LexerError);

    try {
      tokenize('"hello');
    } catch (err) {
      expect(err).toBeInstanceOf(LexerError);
      const lexerError = err as LexerError;
      expect(lexerError.position.line).toBe(1);
      expect(lexerError.position.column).toBe(1);
      expect(lexerError.message).toContain("Unclosed quoted string");
    }
  });

  test("unclosed single quote returns LexerError with position", () => {
    expect(() => tokenize("'hello")).toThrow(LexerError);

    try {
      tokenize("'hello");
    } catch (err) {
      expect(err).toBeInstanceOf(LexerError);
      const lexerError = err as LexerError;
      expect(lexerError.position.line).toBe(1);
      expect(lexerError.position.column).toBe(1);
      expect(lexerError.message).toContain("Unclosed quoted string");
    }
  });

  test("document start marker (---) returns correct token", () => {
    const types = getTokenTypes("---");
    expect(types).toEqual(["DOCUMENT_START", "EOF"]);
  });

  test("document end marker (...) returns correct token", () => {
    const types = getTokenTypes("...");
    expect(types).toEqual(["DOCUMENT_END", "EOF"]);
  });

  test("document markers with content return correct tokens", () => {
    const types = getTokenTypes("---\ndata\n...");
    expect(types).toEqual([
      "DOCUMENT_START",
      "NEWLINE",
      "SCALAR",
      "NEWLINE",
      "DOCUMENT_END",
      "EOF",
    ]);
  });
});

import { describe, expect, test } from "bun:test";
import { tokenize } from "./lexer";
import { validate } from "./parser";

function validateYaml(input: string) {
  const tokens = tokenize(input);
  return validate(tokens);
}

describe("parser", () => {
  test("empty document returns valid: true", () => {
    const result = validateYaml("");
    expect(result.valid).toBe(true);
  });

  test("comment-only document returns valid: true", () => {
    const result = validateYaml("# this is a comment");
    expect(result.valid).toBe(true);
  });

  test("simple mapping returns valid: true", () => {
    const result = validateYaml("key: value");
    expect(result.valid).toBe(true);
  });

  test("nested mapping returns valid: true", () => {
    const result = validateYaml("a:\n  b: c");
    expect(result.valid).toBe(true);
  });

  test("sequence returns valid: true", () => {
    const result = validateYaml("- a\n- b");
    expect(result.valid).toBe(true);
  });

  test("mixed structure (mapping with sequence values) returns valid: true", () => {
    const result = validateYaml("list:\n  - item1\n  - item2");
    expect(result.valid).toBe(true);
  });

  test("invalid indentation returns valid: false with error position", () => {
    const result = validateYaml("a:\n  b: c\n d: e");
    expect(result.valid).toBe(false);

    if (!result.valid) {
      expect(result.error.position.line).toBeGreaterThan(0);
      expect(result.error.position.column).toBeGreaterThan(0);
      expect(result.error.message).toContain("indentation");
    }
  });

  test("tab character returns valid: false (tabs not allowed)", () => {
    const result = validateYaml("\tkey: value");
    expect(result.valid).toBe(false);

    if (!result.valid) {
      expect(result.error.message.toLowerCase()).toContain("tab");
    }
  });
});

import { describe, expect, test, beforeAll, afterAll } from "bun:test";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

const CLI_PATH = join(import.meta.dir, "validate-yaml.ts");

async function runCli(
  args: string[]
): Promise<{ stdout: string; stderr: string; exitCode: number }> {
  const proc = Bun.spawn(["bun", "run", CLI_PATH, ...args], {
    stdout: "pipe",
    stderr: "pipe",
  });

  const [stdout, stderr] = await Promise.all([
    new Response(proc.stdout).text(),
    new Response(proc.stderr).text(),
  ]);

  const exitCode = await proc.exited;

  return { stdout, stderr, exitCode };
}

describe("validate-yaml CLI integration tests", () => {
  let tempDir: string;

  beforeAll(async () => {
    tempDir = await mkdtemp(join(tmpdir(), "yaml-validator-test-"));
  });

  afterAll(async () => {
    await rm(tempDir, { recursive: true, force: true });
  });

