        "content": "import { describe, expect, test } from \"bun:test\";\nimport { validateYaml } from \"./yaml-validate\";\n\ndescribe(\"validateYaml\", () => {\n  describe(\"valid YAML\", () => {\n    test(\"validates simple key-value pairs\", () => {\n      const yaml = `\nname: John\nage: 30\nactive: true\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"validates nested objects\", () => {\n      const yaml = `\nperson:\n  name: John\n  address:\n    city: New York\n    zip: 10001\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"validates arrays/lists\", () => {\n      const yaml = `\nfruits:\n  - apple\n  - banana\n  - cherry\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"validates inline list syntax in values\", () => {\n      const yaml = `\ncolors:\n  - red\n  - green\n  - blue\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"validates quoted strings with special characters\", () => {\n      const yaml = `\nmessage: \"Hello: World\"\nanother: 'Key: Value'\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"validates empty input\", () => {\n      const result = validateYaml(\"\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"validates whitespace-only input\", () => {\n      const result = validateYaml(\"   \\n  \\n   \");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"validates comments\", () => {\n      const yaml = 