        "file_path": "/private/tmp/rp1-evals/f4c1cefd/yaml-validator-worktree/src/yaml-validate.ts",
        "content": "/**\n * YAML Validator Module\n *\n * A lightweight YAML syntax validator without external dependencies.\n * Validates basic YAML structure and reports errors with line numbers.\n */\n\nexport interface ValidationError {\n  line: number;\n  column: number;\n  message: string;\n}\n\nexport interface ValidationResult {\n  valid: boolean;\n  errors: ValidationError[];\n}\n\ninterface IndentLevel {\n  spaces: number;\n  isListItem: boolean;\n}\n\n/**\n * Validates YAML content and returns validation result.\n */\nexport function validateYaml(content: string): ValidationResult {\n  const errors: ValidationError[] = [];\n\n  if (!content || content.trim() === \"\") {\n    return { valid: true, errors: [] };\n  }\n\n  const lines = content.split(\"\\n\");\n  const indentStack: IndentLevel[] = [{ spaces: 0, isListItem: false }];\n  const keysAtLevel: Map<number, Set<string>> = new Map();\n  let inMultilineString = false;\n  let multilineIndent = 0;\n\n  for (let i = 0; i < lines.length; i++) {\n    const lineNum = i + 1;\n    const line = lines[i];\n\n    // Skip empty lines\n    if (line.trim() === \"\") {\n      continue;\n    }\n\n    // Skip comment lines\n    if (line.trim().startsWith(\"#\")) {\n      continue;\n    }\n\n    // Skip document markers\n    if (line === \"---\" || line === \"...\") {\n      continue;\n    }\n\n    // Check for tab characters\n    const tabIndex = line.indexOf(\"\\t\");\n    if (tabIndex !== -1) {\n      errors.push({\n        line: lineNum,\n        column: tabIndex + 1,\n        message: \"Tab character found; YAML requires spaces for indentation\",\n      });\n      continue;\n    }\n\n    // Calculate indentation\n    const leadingSpaces = line.match(/^( *)/)?.[1].length ?? 0;\n    const trimmedLine = line.trim();\n\n    // Handle multiline string content\n    if (inMultilineString) {\n      if (leadingSpaces <= multilineIndent && trimmedLine !== \"\") {\n        inMultilineString = false;\n      } else {\n        continue;\n      }\n    }\n\n    // Check for multiline string indicators\n    if (trimmedLine.endsWith(\"|\") || trimmedLine.endsWith(\">\") ||\n        trimmedLine.endsWith(\"|-\") || trimmedLine.endsWith(\">-\") ||\n        trimmedLine.endsWith(\"|+\") || trimmedLine.endsWith(\">+\")) {\n      inMultilineString = true;\n      multilineIndent = leadingSpaces;\n    }\n\n    // Validate indentation consistency\n    if (leadingSpaces > 0 && leadingSpaces % 2 !== 0) {\n      // Allow odd indentation if it follows a list item pattern\n      const isListContinuation = indentStack.some(\n        (level) => level.isListItem && leadingSpaces === level.spaces + 2\n      );\n      if (!isListContinuation) {\n        errors.push({\n          line: lineNum,\n          column: 1,\n          message: `Inconsistent indentation: ${leadingSpaces} spaces (expected even number)`,\n        });\n      }\n    }\n\n    // Check for unclosed quotes\n    const quoteError = checkUnclosedQuotes(trimmedLine, lineNum);\n    if (quoteError) {\n      errors.push(quoteError);\n      continue;\n    }\n\n    // Determine if this is a list item\n    const isListItem = trimmedLine.startsWith(\"- \");\n    const listItemContent = isListItem ? trimmedLine.slice(2) : trimmedLine;\n\n    // Validate key-value structure\n    if (!isListItem || listItemContent.includes(\":\")) {\n      const contentToCheck = isListItem ? listItemContent : trimmedLine;\n      const keyValueError = validateKeyValue(contentToCheck, lineNum, leadingSpaces + (isListItem ? 2 : 0));\n      if (keyValueError) {\n        errors.push(keyValueError);\n        continue;\n      }\n\n      // Check for duplicate keys at the same level\n      const key = extractKey(contentToCheck);\n      if (key) {\n        const level = leadingSpaces;\n        if (!keysAtLevel.has(level)) {\n          keysAtLevel.set(level, new Set());\n        }\n        const keysSet = keysAtLevel.get(level)!;\n\n        // Clear keys at deeper levels when we go back up\n        for (const [l, _] of keysAtLevel) {\n          if (l > level) {\n            keysAtLevel.delete(l);\n          }\n        }\n\n        if (keysSet.has(key)) {\n          errors.push({\n            line: lineNum,\n            column: leadingSpaces + 1,\n            message: `Duplicate key '${key}' at this indentation level`,\n          });\n        } else {\n          keysSet.add(key);\n        }\n      }\n    }\n\n    // Validate list item format\n    if (trimmedLine.startsWith(\"-\") && !trimmedLine.startsWith(\"- \") && trimmedLine !== \"-\") {\n      errors.push({\n        line: lineNum,\n        column: leadingSpaces + 1,\n        message: \"List item must have a space after the dash\",\n      });\n    }\n\n    // Update indent stack\n    while (indentStack.length > 1 && indentStack[indentStack.length - 1].spaces >= leadingSpaces) {\n      indentStack.pop();\n    }\n    indentStack.push({ spaces: leadingSpaces, isListItem });\n  }\n\n  return {\n    valid: errors.length === 0,\n    errors,\n  };\n}\n\n/**\n * Checks for unclosed quotes in a line.\n */\nfunction checkUnclosedQuotes(line: string, lineNum: number): ValidationError | null {\n  let inSingleQuote = false;\n  let inDoubleQuote = false;\n  let quoteStart = 0;\n\n  for (let i = 0; i < line.length; i++) {\n    const char = line[i];\n    const prevChar = i > 0 ? line[i - 1] : \"\";\n\n    if (char === \"'\" && !inDoubleQuote && prevChar !== \"\\\\\") {\n      if (!inSingleQuote) {\n        inSingleQuote = true;\n        quoteStart = i + 1;\n      } else {\n        inSingleQuote = false;\n      }\n    } else if (char === '\"' && !inSingleQuote && prevChar !== \"\\\\\") {\n      if (!inDoubleQuote) {\n        inDoubleQuote = true;\n        quoteStart = i + 1;\n      } else {\n        inDoubleQuote = false;\n      }\n    }\n  }\n\n  if (inSingleQuote || inDoubleQuote) {\n    return {\n      line: lineNum,\n      column: quoteStart,\n      message: `Unclosed ${inSingleQuote ? \"single\" : \"double\"} quote`,\n    };\n  }\n\n  return null;\n}\n\n/**\n * Validates key-value pair syntax.\n */\nfunction validateKeyValue(content: string, lineNum: number, column: number): ValidationError | null {\n  // Skip if it's just a value (no colon) or a plain scalar\n  if (!content.includes(\":\")) {\n    return null;\n  }\n\n  // Skip if it's a quoted string containing colons\n  const colonIndex = findUnquotedColon(content);\n  if (colonIndex === -1) {\n    return null;\n  }\n\n  const key = content.slice(0, colonIndex).trim();\n\n  // Check for empty key\n  if (key === \"\") {\n    return {\n      line: lineNum,\n      column,\n      message: \"Empty key before colon\",\n    };\n  }\n\n  // Check for invalid key characters (unquoted)\n  if (!key.startsWith('\"') && !key.startsWith(\"'\")) {\n    const invalidChars = /^[@`]/;\n    if (invalidChars.test(key)) {\n      return {\n        line: lineNum,\n        column,\n        message: `Invalid key format: keys cannot start with '${key[0]}'`,\n      };\n    }\n  }\n\n  return null;\n}\n\n/**\n * Finds the index of a colon that's not inside quotes.\n */\nfunction findUnquotedColon(content: string): number {\n  let inSingleQuote = false;\n  let inDoubleQuote = false;\n\n  for (let i = 0; i < content.length; i++) {\n    const char = content[i];\n    const prevChar = i > 0 ? content[i - 1] : \"\";\n\n    if (char === \"'\" && !inDoubleQuote && prevChar !== \"\\\\\") {\n      inSingleQuote = !inSingleQuote;\n    } else if (char === '\"' && !inSingleQuote && prevChar !== \"\\\\\") {\n      inDoubleQuote = !inDoubleQuote;\n    } else if (char === \":\" && !inSingleQuote && !inDoubleQuote) {\n      return i;\n    }\n  }\n\n  return -1;\n}\n\n/**\n * Extracts the key from a key-value line.\n */\nfunction extractKey(content: string): string | null {\n  const colonIndex = findUnquotedColon(content);\n  if (colonIndex === -1) {\n    return null;\n  }\n\n  const key = content.slice(0, colonIndex).trim();\n\n  // Remove quotes if present\n  if ((key.startsWith('\"') && key.endsWith('\"')) ||\n      (key.startsWith(\"'\") && key.endsWith(\"'\"))) {\n    return key.slice(1, -1);\n  }\n\n  return key;\n}\n"
      },
