        "file_path": "/private/tmp/rp1-evals/f4c1cefd/yaml-validator-worktree/src/yaml-validator.ts",
        "content": "#!/usr/bin/env bun\n/**\n * YAML Validator CLI\n *\n * Validates YAML files for syntax errors.\n *\n * Usage:\n *   bun run src/yaml-validator.ts <file>   - Validate a file\n *   cat file.yaml | bun run src/yaml-validator.ts -   - Validate from stdin\n */\n\nimport { validateYaml } from \"./yaml-validate\";\n\nasync function main(): Promise<void> {\n  const args = process.argv.slice(2);\n\n  if (args.length === 0) {\n    console.error(\"Usage: yaml-validator <file> | yaml-validator -\");\n    console.error(\"\");\n    console.error(\"  <file>  Path to YAML file to validate\");\n    console.error(\"  -       Read YAML from stdin\");\n    process.exit(1);\n  }\n\n  const input = args[0];\n  let content: string;\n\n  try {\n    if (input === \"-\") {\n      // Read from stdin\n      content = await readStdin();\n    } else {\n      // Read from file\n      const file = Bun.file(input);\n      if (!(await file.exists())) {\n        console.error(`Error: File not found: ${input}`);\n        process.exit(1);\n      }\n      content = await file.text();\n    }\n  } catch (err) {\n    console.error(`Error reading input: ${err}`);\n    process.exit(1);\n  }\n\n  const result = validateYaml(content);\n\n  if (result.valid) {\n    console.log(\"✓ YAML is valid\");\n    process.exit(0);\n  } else {\n    console.error(\"✗ YAML validation failed:\");\n    console.error(\"\");\n    for (const error of result.errors) {\n      console.error(`  Line ${error.line}, Column ${error.column}: ${error.message}`);\n    }\n    process.exit(1);\n  }\n}\n\nasync function readStdin(): Promise<string> {\n  const chunks: Buffer[] = [];\n\n  for await (const chunk of Bun.stdin.stream()) {\n    chunks.push(Buffer.from(chunk));\n  }\n\n  return Buffer.concat(chunks).toString(\"utf-8\");\n}\n\nmain();\n"
      },
      "source": "stream_event"
    },
