        "content": "import { describe, expect, test } from \"bun:test\";\nimport { validateYaml } from \"./yaml-validate\";\n\ndescribe(\"validateYaml\", () => {\n  describe(\"valid YAML\", () => {\n    test(\"validates simple key-value pairs\", () => {\n      const yaml = `\nname: John\nage: 30\nactive: true\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"validates nested objects\", () => {\n      const yaml = `\nperson:\n  name: John\n  address:\n    city: New York\n    zip: 10001\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"validates arrays/lists\", () => {\n      const yaml = `\nfruits:\n  - apple\n  - banana\n  - cherry\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"validates inline list syntax in values\", () => {\n      const yaml = `\ncolors:\n  - red\n  - green\n  - blue\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"validates quoted strings with special characters\", () => {\n      const yaml = `\nmessage: \"Hello: World\"\nanother: 'Key: Value'\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"validates empty input\", () => {\n      const result = validateYaml(\"\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"validates whitespace-only input\", () => {\n      const result = validateYaml(\"   \\n  \\n   \");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"validates comments\", () => {\n      const yaml = `\n# This is a comment\nname: John  # inline comment\n# Another comment\nage: 30\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"validates document markers\", () => {\n      const yaml = `---\nname: John\nage: 30\n...`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"validates multiline strings with pipe\", () => {\n      const yaml = `\ndescription: |\n  This is a multiline\n  string that spans\n  multiple lines\nname: John\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"validates multiline strings with folded style\", () => {\n      const yaml = `\ndescription: >\n  This is a folded\n  multiline string\nname: John\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"validates list of objects\", () => {\n      const yaml = `\nusers:\n  - name: Alice\n    age: 25\n  - name: Bob\n    age: 30\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n  });\n\n  describe(\"invalid YAML\", () => {\n    test(\"detects tab characters\", () => {\n      const yaml = \"name:\\tJohn\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors).toHaveLength(1);\n      expect(result.errors[0].message).toContain(\"Tab character\");\n    });\n\n    test(\"detects unclosed double quotes\", () => {\n      const yaml = 'name: \"John';\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors).toHaveLength(1);\n      expect(result.errors[0].message).toContain(\"Unclosed\");\n      expect(result.errors[0].message).toContain(\"double quote\");\n    });\n\n    test(\"detects unclosed single quotes\", () => {\n      const yaml = \"name: 'John\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors).toHaveLength(1);\n      expect(result.errors[0].message).toContain(\"Unclosed\");\n      expect(result.errors[0].message).toContain(\"single quote\");\n    });\n\n    test(\"detects duplicate keys at same level\", () => {\n      const yaml = `\nname: John\nage: 30\nname: Jane\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors).toHaveLength(1);\n      expect(result.errors[0].message).toContain(\"Duplicate key\");\n      expect(result.errors[0].message).toContain(\"name\");\n    });\n\n    test(\"detects invalid key starting with @\", () => {\n      const yaml = \"@invalid: value\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors).toHaveLength(1);\n      expect(result.errors[0].message).toContain(\"Invalid key format\");\n    });\n\n    test(\"detects list item without space after dash\", () => {\n      const yaml = `\nitems:\n  -item1\n  - item2\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors).toHaveLength(1);\n      expect(result.errors[0].message).toContain(\"space after the dash\");\n    });\n\n    test(\"detects empty key\", () => {\n      const yaml = \": value\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors).toHaveLength(1);\n      expect(result.errors[0].message).toContain(\"Empty key\");\n    });\n  });\n\n  describe(\"error reporting\", () => {\n    test(\"reports correct line numbers\", () => {\n      const yaml = `\nname: John\nage: 30\ninvalid:\\ttab\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors[0].line).toBe(4);\n    });\n\n    test(\"reports correct column numbers for tabs\", () => {\n      const yaml = \"name:\\tvalue\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors[0].column).toBe(6);\n    });\n\n    test(\"accumulates multiple errors\", () => {\n      const yaml = `\nname:\\tJohn\nage: \"unclosed\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThanOrEqual(2);\n    });\n  });\n\n  describe(\"edge cases\", () => {\n    test(\"handles keys with colons in quoted values\", () => {\n      const yaml = `\ntime: \"12:30:00\"\nurl: 'http://example.com'\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"allows duplicate keys at different indentation levels\", () => {\n      const yaml = `\nparent:\n  name: Child\nname: Parent\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"handles deeply nested structures\", () => {\n      const yaml = `\nlevel1:\n  level2:\n    level3:\n      level4:\n        value: deep\n`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n  });\n});\n"
