  isListItem: boolean;
}

/**
 * Validates YAML content and returns validation result.
 */
export function validateYaml(content: string): ValidationResult {
  const errors: ValidationError[] = [];

  if (!content || content.trim() === "") {
    return { valid: true, errors: [] };
  }

  const lines = content.split("\n");
  const indentStack: IndentLevel[] = [{ spaces: 0, isListItem: false }];
  const keysAtLevel: Map<number, Set<string>> = new Map();
  let inMultilineString = false;
  let multilineIndent = 0;

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1;
    const line = lines[i];

    // Skip empty lines
    if (line.trim() === "") {
      continue;
    }

    // Skip comment lines
    if (line.trim().startsWith("#")) {
      continue;
    }

    // Skip document markers
    if (line === "---" || line === "...") {
      continue;
    }

    // Check for tab characters
    const tabIndex = line.indexOf("\t");
    if (tabIndex !== -1) {
      errors.push({
        line: lineNum,
        column: tabIndex + 1,
        message: "Tab character found; YAML requires spaces for indentation",
      });
      continue;
    }

    // Calculate indentation
    const leadingSpaces = line.match(/^( *)/)?.[1].length ?? 0;
    const trimmedLine = line.trim();

    // Handle multiline string content
    if (inMultilineString) {
      if (leadingSpaces <= multilineIndent && trimmedLine !== "") {
        inMultilineString = false;
      } else {
        continue;
      }
    }

    // Check for multiline string indicators
    if (trimmedLine.endsWith("|") || trimmedLine.endsWith(">") ||
        trimmedLine.endsWith("|-") || trimmedLine.endsWith(">-") ||
        trimmedLine.endsWith("|+") || trimmedLine.endsWith(">+")) {
      inMultilineString = true;
      multilineIndent = leadingSpaces;
    }

    // Validate indentation consistency
    if (leadingSpaces > 0 && leadingSpaces % 2 !== 0) {
      // Allow odd indentation if it follows a list item pattern
      const isListContinuation = indentStack.some(
        (level) => level.isListItem && leadingSpaces === level.spaces + 2
      );
      if (!isListContinuation) {
        errors.push({
          line: lineNum,
          column: 1,
          message: `Inconsistent indentation: ${leadingSpaces} spaces (expected even number)`,
        });
      }
    }

    // Check for unclosed quotes
    const quoteError = checkUnclosedQuotes(trimmedLine, lineNum);
    if (quoteError) {
      errors.push(quoteError);
      continue;
    }

    // Determine if this is a list item
    const isListItem = trimmedLine.startsWith("- ");
    const listItemContent = isListItem ? trimmedLine.slice(2) : trimmedLine;

    // Validate key-value structure
    if (!isListItem || listItemContent.includes(":")) {
      const contentToCheck = isListItem ? listItemContent : trimmedLine;
      const keyValueError = validateKeyValue(contentToCheck, lineNum, leadingSpaces + (isListItem ? 2 : 0));
      if (keyValueError) {
        errors.push(keyValueError);
        continue;
      }

      // Check for duplicate keys at the same level
      const key = extractKey(contentToCheck);
      if (key) {
        const level = leadingSpaces;
        if (!keysAtLevel.has(level)) {
          keysAtLevel.set(level, new Set());
        }
        const keysSet = keysAtLevel.get(level)!;

        // Clear keys at deeper levels when we go back up
        for (const [l, _] of keysAtLevel) {
          if (l > level) {
            keysAtLevel.delete(l);
          }
        }

        if (keysSet.has(key)) {
          errors.push({
            line: lineNum,
            column: leadingSpaces + 1,
            message: `Duplicate key '${key}' at this indentation level`,
          });
        } else {
          keysSet.add(key);
        }
      }
    }

    // Validate list item format
    if (trimmedLine.startsWith("-") && !trimmedLine.startsWith("- ") && trimmedLine !== "-") {
      errors.push({
        line: lineNum,
        column: leadingSpaces + 1,
        message: "List item must have a space after the dash",
      });
    }

    // Update indent stack
    while (indentStack.length > 1 && indentStack[indentStack.length - 1].spaces >= leadingSpaces) {
      indentStack.pop();
    }
    indentStack.push({ spaces: leadingSpaces, isListItem });
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

/**
 * Checks for unclosed quotes in a line.
 */
function checkUnclosedQuotes(line: string, lineNum: number): ValidationError | null {
  let inSingleQuote = false;
  let inDoubleQuote = false;
  let quoteStart = 0;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    const prevChar = i > 0 ? line[i - 1] : "";

    if (char === "'" && !inDoubleQuote && prevChar !== "\\") {
      if (!inSingleQuote) {
        inSingleQuote = true;
        quoteStart = i + 1;
      } else {
        inSingleQuote = false;
      }
    } else if (char === '"' && !inSingleQuote && prevChar !== "\\") {
      if (!inDoubleQuote) {
        inDoubleQuote = true;
        quoteStart = i + 1;
      } else {
        inDoubleQuote = false;
      }
    }
  }

  if (inSingleQuote || inDoubleQuote) {
    return {
      line: lineNum,
      column: quoteStart,
      message: `Unclosed ${inSingleQuote ? "single" : "double"} quote`,
    };
  }

  return null;
}

/**
 * Validates key-value pair syntax.
 */
function validateKeyValue(content: string, lineNum: number, column: number): ValidationError | null {
  // Skip if it's just a value (no colon) or a plain scalar
  if (!content.includes(":")) {
    return null;
  }

  // Skip if it's a quoted string containing colons
  const colonIndex = findUnquotedColon(content);
  if (colonIndex === -1) {
    return null;
  }

  const key = content.slice(0, colonIndex).trim();

  // Check for empty key
  if (key === "") {
    return {
      line: lineNum,
      column,
      message: "Empty key before colon",
    };
  }

  // Check for invalid key characters (unquoted)
  if (!key.startsWith('"') && !key.startsWith("'")) {
    const invalidChars = /^[@`]/;
    if (invalidChars.test(key)) {
      return {
        line: lineNum,
        column,
        message: `Invalid key format: keys cannot start with '${key[0]}'`,
      };
    }
  }

  return null;
}

/**
 * Finds the index of a colon that's not inside quotes.
 */
function findUnquotedColon(content: string): number {
  let inSingleQuote = false;
  let inDoubleQuote = false;

  for (let i = 0; i < content.length; i++) {
    const char = content[i];
    const prevChar = i > 0 ? content[i - 1] : "";

    if (char === "'" && !inDoubleQuote && prevChar !== "\\") {
      inSingleQuote = !inSingleQuote;
    } else if (char === '"' && !inSingleQuote && prevChar !== "\\") {
      inDoubleQuote = !inDoubleQuote;
    } else if (char === ":" && !inSingleQuote && !inDoubleQuote) {
      return i;
    }
  }

  return -1;
}

/**
 * Extracts the key from a key-value line.
 */
function extractKey(content: string): string | null {
  const colonIndex = findUnquotedColon(content);
  if (colonIndex === -1) {
    return null;
  }

  const key = content.slice(0, colonIndex).trim();

  // Remove quotes if present
  if ((key.startsWith('"') && key.endsWith('"')) ||
      (key.startsWith("'") && key.endsWith("'"))) {
    return key.slice(1, -1);
  }

  return key;
}

#!/usr/bin/env bun
/**
 * YAML Validator CLI
 *
 * Validates YAML files for syntax errors.
 *
 * Usage:
 *   bun run src/yaml-validator.ts <file>   - Validate a file
 *   cat file.yaml | bun run src/yaml-validator.ts -   - Validate from stdin
 */

import { validateYaml } from "./yaml-validate";

async function main(): Promise<void> {
  const args = process.argv.slice(2);

  if (args.length === 0) {
    console.error("Usage: yaml-validator <file> | yaml-validator -");
    console.error("");
    console.error("  <file>  Path to YAML file to validate");
    console.error("  -       Read YAML from stdin");
    process.exit(1);
  }

  const input = args[0];
  let content: string;

  try {
    if (input === "-") {
      // Read from stdin
      content = await readStdin();
    } else {
      // Read from file
      const file = Bun.file(input);
      if (!(await file.exists())) {
        console.error(`Error: File not found: ${input}`);
        process.exit(1);
      }
      content = await file.text();
    }
  } catch (err) {
    console.error(`Error reading input: ${err}`);
    process.exit(1);
  }

  const result = validateYaml(content);

  if (result.valid) {
    console.log("✓ YAML is valid");
    process.exit(0);
  } else {
    console.error("✗ YAML validation failed:");
    console.error("");
    for (const error of result.errors) {
      console.error(`  Line ${error.line}, Column ${error.column}: ${error.message}`);
    }
    process.exit(1);
  }
}

async function readStdin(): Promise<string> {
  const chunks: Buffer[] = [];

  for await (const chunk of Bun.stdin.stream()) {
    chunks.push(Buffer.from(chunk));
  }

  return Buffer.concat(chunks).toString("utf-8");
}

main();

import { describe, expect, test } from "bun:test";
import { validateYaml } from "./yaml-validate";

describe("validateYaml", () => {
  describe("valid YAML", () => {
    test("validates simple key-value pairs", () => {
      const yaml = `
name: John
age: 30
active: true
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates nested objects", () => {
      const yaml = `
person:
  name: John
  address:
    city: New York
    zip: 10001
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates arrays/lists", () => {
      const yaml = `
fruits:
  - apple
  - banana
  - cherry
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates inline list syntax in values", () => {
      const yaml = `
colors:
  - red
  - green
  - blue
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates quoted strings with special characters", () => {
      const yaml = `
message: "Hello: World"
another: 'Key: Value'
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates empty input", () => {
      const result = validateYaml("");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates whitespace-only input", () => {
      const result = validateYaml("   \n  \n   ");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates comments", () => {
      const yaml = `
# This is a comment
name: John  # inline comment
# Another comment
age: 30
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates document markers", () => {
      const yaml = `---
name: John
age: 30
...`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates multiline strings with pipe", () => {
      const yaml = `
description: |
  This is a multiline
  string that spans
  multiple lines
name: John
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates multiline strings with folded style", () => {
      const yaml = `
description: >
  This is a folded
  multiline string
name: John
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates list of objects", () => {
      const yaml = `
users:
  - name: Alice
    age: 25
  - name: Bob
    age: 30
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });
  });

  describe("invalid YAML", () => {
    test("detects tab characters", () => {
      const yaml = "name:\tJohn";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(1);
      expect(result.errors[0].message).toContain("Tab character");
    });

    test("detects unclosed double quotes", () => {
      const yaml = 'name: "John';
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(1);
      expect(result.errors[0].message).toContain("Unclosed");
      expect(result.errors[0].message).toContain("double quote");
    });

    test("detects unclosed single quotes", () => {
      const yaml = "name: 'John";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(1);
      expect(result.errors[0].message).toContain("Unclosed");
      expect(result.errors[0].message).toContain("single quote");
    });

    test("detects duplicate keys at same level", () => {
      const yaml = `
name: John
age: 30
name: Jane
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(1);
      expect(result.errors[0].message).toContain("Duplicate key");
      expect(result.errors[0].message).toContain("name");
    });

    test("detects invalid key starting with @", () => {
      const yaml = "@invalid: value";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(1);
      expect(result.errors[0].message).toContain("Invalid key format");
    });

    test("detects list item without space after dash", () => {
      const yaml = `
items:
  -item1
  - item2
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(1);
      expect(result.errors[0].message).toContain("space after the dash");
    });

    test("detects empty key", () => {
      const yaml = ": value";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(1);
      expect(result.errors[0].message).toContain("Empty key");
    });
  });

  describe("error reporting", () => {
    test("reports correct line numbers", () => {
      const yaml = `
name: John
age: 30
invalid:\ttab
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors[0].line).toBe(4);
    });

    test("reports correct column numbers for tabs", () => {
      const yaml = "name:\tvalue";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors[0].column).toBe(6);
    });

    test("accumulates multiple errors", () => {
      const yaml = `
name:\tJohn
age: "unclosed
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThanOrEqual(2);
    });
  });

  describe("edge cases", () => {
    test("handles keys with colons in quoted values", () => {
      const yaml = `
time: "12:30:00"
url: 'http://example.com'
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("allows duplicate keys at different indentation levels", () => {
      const yaml = `
parent:
  name: Child
name: Parent
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("handles deeply nested structures", () => {
      const yaml = `
level1:
  level2:
    level3:
      level4:
        value: deep
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });
  });
});

